from ibm_watsonx_orchestrate.agent_builder.tools import tool, expect_credentials
@tool @expect_credentials(["api_url"]) def my_tool(input_data: MyInput, credentials: dict) -> MyOutput: """ Tool that requires API URL as credential.
Args: input_data: Tool input parameters credentials: Dictionary containing 'api_url' """ api_url = credentials.get("api_url")
if not api_url: raise ValueError("api_url credential is required")
# Use api_url for API calls response = requests.get(f"{api_url}/api/endpoint") # ...

implementation_pattern.tool_template:
""" FleetOps Tool with Proper API Configuration
This tool demonstrates the correct pattern for API endpoint configuration. """
from typing import Dict, Any from pydantic import BaseModel, Field from ibm_watsonx_orchestrate.agent_builder.tools import tool import requests import os
class ToolInput(BaseModel): """Input schema""" param: str = Field(description="Parameter description")
class ToolOutput(BaseModel): """Output schema""" result: str = Field(description="Result description") status: str = Field(description="Operation status")
@tool def my_fleetops_tool(input_data: ToolInput) -> ToolOutput: """ Tool that integrates with FleetOps API.
Requires FLEETOPS_API_URL environment variable to be set.
Args: input_data: Tool input parameters
Returns: ToolOutput: Result of operation
Raises: ValueError: If FLEETOPS_API_URL is not configured requests.RequestException: If API call fails """ # Get API URL from environment - NEVER use hardcoded fallback api_url = os.environ.get('FLEETOPS_API_URL')
if not api_url: raise ValueError( "FLEETOPS_API_URL environment variable is not set. " "Please configure your FleetOps API endpoint before using this tool. " "Example: export FLEETOPS_API_URL='https://your-api.example.com'" )
# Validate URL format (optional but recommended) if not api_url.startswith(('http://', 'https://')): raise ValueError( f"Invalid FLEETOPS_API_URL format: {api_url}. " "URL must start with http:// or https://" )
timeout = 10
try: # Make API call response = requests.get( f"{api_url}/api/endpoint", timeout=timeout, headers={"Content-Type": "application/json"} ) response.raise_for_status() data = response.json()
return ToolOutput( result="Success", status="OK" )
except requests.Timeout: raise Exception(f"API request to {api_url} timed out after {timeout}s") except requests.RequestException as e: raise Exception(f"API request failed: {str(e)}") except Exception as e: raise Exception(f"Unexpected error: {str(e)}")

